package com.veritas.controller;
import com.veritas.model.UserAccount;import com.veritas.repository.UserRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import jakarta.validation.constraints.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class RegistrationController {private final UserRepository users;private final PasswordEncoder encoder;public RegistrationController(UserRepository u,PasswordEncoder p){users=u;encoder=p;}
 @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Registration r){if(r.username==null||r.username.trim().length()<3||r.password==null||r.password.length()<8)return ResponseEntity.badRequest().body(Map.of("error","Username must be at least 3 characters and password at least 8 characters."));if(users.existsByUsername(r.username.trim()))return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","Username already exists."));users.save(new UserAccount(r.username.trim(),encoder.encode(r.password),"CITIZEN"));return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","Citizen account created. Login using the web form."));}
 public static class Registration {public String username;public String password;}}
